// ============================================================
// PARSE ARCGIS FEATURES TO NOTION HUB SCHEMA (DEEP LINK FIX)
// ============================================================
const rawData = $input.first().json;

if (!rawData || !rawData.features || rawData.features.length === 0) {
  return [{ json: { error: "No features found. Server might be down or query failed.", source: "Pinal ArcGIS", unique_id: "skip" } }];
}

const features = rawData.features;
const results = [];

for (const feature of features) {
  const attr = feature.attributes || {};

  const getVal = (keywords) => {
    const key = Object.keys(attr).find(k => keywords.some(kw => k.toLowerCase().includes(kw)));
    return key ? attr[key] : null;
  };

  const parcelNumber = getVal(['parcel', 'apn', 'pin', 'taxcode']) || "Unknown";
  let address = getVal(['address', 'situs', 'location']) || "";
  const owner = getVal(['owner', 'name']) || "Unknown Owner";

  let displayParcel = parcelNumber;
  if (displayParcel && displayParcel.length === 9) {
    displayParcel = displayParcel.replace(/^(.{3})(.{2})(.{3})(.{1})$/, "$1-$2-$3-$4");
  }

  if (!address || address.toString().trim().toLowerCase() === 'not available') {
    address = `Parcel: ${displayParcel}`;
  }

  address = `${address} | Owner: ${owner}`;

  let bidAmount = getVal(['amount', 'due', 'tax', 'face', 'total', 'purchasetotal']) || 0;
  if (typeof bidAmount === 'string') {
      bidAmount = parseFloat(bidAmount.replace(/[^\d.]/g, '')) || 0;
  }

  const county = "Pinal County";
  const state = "AZ";

  // --- THE SENIOR FIX: DIRECT ASSESSOR DEEP LINK ---
  let cleanParcel = parcelNumber.replace(/[^a-zA-Z0-9]/g, '');
  const auctionUrl = cleanParcel !== "Unknown" 
    ? `https://app1.pinal.gov/Search/Parcel-Details.aspx?Parcel_ID=${cleanParcel}` 
    : "https://experience.arcgis.com/experience/ad75946c98f44dc58ccc635553947a27/";

  const uniqueId = `arcgis|${county}|${parcelNumber}`.toLowerCase().replace(/[^a-z0-9|]/g, '');

  results.push({
    json: {
      property_address: address,
      county: county,
      state: state,
      source: "RealTaxLien - Pinal AZ",
      status: "Upcoming",
      sale_date: "Check Listing",
      bidding_date: "Check Listing",
      bidding_time: "Check Listing",
      current_bid: bidAmount,
      auction_url: auctionUrl,
      time_remaining: "",
      unique_id: uniqueId
    }
  });
}

const LIMITED = results.slice(0, 10);
console.log(`✅ ArcGIS: ${LIMITED.length} properties passed (capped at 10)`);
return LIMITED;
